cssCode:
.neon-text { 
  font-size: 28px; font-weight: bold; 
  color: transparent; 
  -webkit-text-stroke: 1px #00ffcc; 
  text-shadow: 0 0 0px rgba(0,255,204,0); 
  animation: textReveal 2s infinite alternate; 
  font-family: sans-serif; letter-spacing: 4px; 
}
@keyframes textReveal { 
  0% { text-shadow: 0 0 0px rgba(0,255,204,0); color: transparent; } 
  100% { text-shadow: 0 0 20px #00ffcc, 0 0 40px #00ffcc; color: #fff; } 
}

